C = [[8, 6, 10, 9],
     [9, 12, 13, 7],
     [14, 9, 16, 5]]
arz, talep = [30, 40, 30], [20, 25, 35, 20]
m, n = 3, 4


def maliyet(X):
    return sum(C[i][j]*X[i][j] for i in range(m) for j in range(n))


def kuzeybati():
    a, b = arz[:], talep[:]
    X = [[0]*n for _ in range(m)]
    i = j = 0
    while i < m and j < n:
        q = min(a[i], b[j]); X[i][j] = q; a[i] -= q; b[j] -= q
        if b[j] == 0 and j < n - 1:
            j += 1
        else:
            i += 1
    return X


def en_kucuk_maliyet():
    a, b = arz[:], talep[:]
    X = [[0]*n for _ in range(m)]
    for c, i, j in sorted((C[i][j], i, j) for i in range(m) for j in range(n)):
        if a[i] > 0 and b[j] > 0:
            q = min(a[i], b[j]); X[i][j] = q; a[i] -= q; b[j] -= q
    return X


def vogel():
    a, b = arz[:], talep[:]
    X = [[0]*n for _ in range(m)]
    R, S = set(range(m)), set(range(n))
    while R and S:
        cz = []
        for i in sorted(R):
            v = sorted(C[i][k] for k in sorted(S))
            cz.append((v[1]-v[0] if len(v) > 1 else v[0], "S", i))
        for j in sorted(S):
            v = sorted(C[k][j] for k in sorted(R))
            cz.append((v[1]-v[0] if len(v) > 1 else v[0], "D", j))
        ceza, tip, idx = max(cz)
        if tip == "S":
            i, j = idx, min(sorted(S), key=lambda j: C[idx][j])
        else:
            i, j = min(sorted(R), key=lambda i: C[i][idx]), idx
        q = min(a[i], b[j]); X[i][j] = q; a[i] -= q; b[j] -= q
        if a[i] == 0:
            R.discard(i)
        if b[j] == 0:
            S.discard(j)
    return X


for ad, X in (("kuzeybati kosesi", kuzeybati()),
              ("en kucuk maliyet", en_kucuk_maliyet()),
              ("Vogel", vogel())):
    dolu = sum(1 for i in range(m) for j in range(n) if X[i][j] > 0)
