import heapq

E = [(1, 2, 4), (1, 3, 2), (2, 3, 1), (2, 4, 5), (3, 4, 8),
     (3, 5, 10), (4, 5, 2), (4, 6, 4), (5, 6, 3)]
N = range(1, 7)
komsu = {i: [] for i in N}
for a, b, w in E:
    komsu[a].append((b, w))
    komsu[b].append((a, w))

# --- en kisa yol (Dijkstra) ---
d = {i: float("inf") for i in N}
d[1] = 0
onceki = {}
pq = [(0, 1)]
while pq:
    du, u = heapq.heappop(pq)
    if du > d[u]:
        continue
    for v, w in komsu[u]:
        if du + w < d[v]:
            d[v] = du + w
            onceki[v] = u
            heapq.heappush(pq, (d[v], v))
print("uzakliklar:", [d[i] for i in N])
yol = [6]
while yol[-1] != 1:
    yol.append(onceki[yol[-1]])
print("1->6 en kisa yol:", list(reversed(yol)), "uzunluk:", d[6])

# --- minimum kapsayan agac (Kruskal) ---
par = {i: i for i in N}


def bul(x):
    while par[x] != x:
        x = par[x]
    return x


mst, toplam = [], 0
for a, b, w in sorted(E, key=lambda e: e[2]):
    ra, rb = bul(a), bul(b)
    if ra != rb:
        par[ra] = rb
        mst.append((a, b, w))
        toplam += w
print("MST kenarlari:", mst)
print("MST toplam:", toplam, "kenar sayisi:", len(mst))
